button { padding: 10px 16px; border: 0; border-radius: 6px; background: #315fce; color: white; font: inherit; cursor: pointer; }
button:hover { background: #244ba9; }
.project-row { justify-content: space-between; padding: 16px 0; border-bottom: 1px solid #e7eaf0; }
.project-row:first-child { margin-top: 20px; border-top: 1px solid #e7eaf0; }
#error-message { color: #a21d2c; }
[hidden] { display: none !important; }
button:focus-visible, input:focus-visible { outline: 3px solid #83a4fa; outline-offset: 2px; }

